<?php
defined('ABSPATH')||exit;
final class GDO_Activator{
	public static function activate(){if(!class_exists('SPD_Helpers')||!class_exists('SDD_Helpers')){deactivate_plugins(plugin_basename(GDO_FILE));wp_die(esc_html__('Activate Files 03 and 07 first.','global-doctor-onboarding'),'',array('back_link'=>true));}$a=get_role('administrator');if($a){$a->add_cap('manage_global_doctor_verification');}global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$c=$wpdb->get_charset_collate();dbDelta("CREATE TABLE {$wpdb->prefix}gdo_documents (id bigint(20) unsigned NOT NULL AUTO_INCREMENT,user_id bigint(20) unsigned NOT NULL,document_type varchar(30) NOT NULL,original_name varchar(255) NOT NULL,mime_type varchar(80) NOT NULL,file_size bigint(20) unsigned NOT NULL,storage_name varchar(100) NOT NULL,uploaded_at datetime NOT NULL,PRIMARY KEY  (id),KEY user_id (user_id),KEY document_type (document_type)) {$c};");$p=get_page_by_path('doctor-application');if(!$p){$id=wp_insert_post(array('post_title'=>'Doctor Application and Verification','post_name'=>'doctor-application','post_content'=>'[gdo_doctor_application]','post_status'=>'publish','post_type'=>'page'));}else{$id=$p->ID;if(get_post_meta($id,'_gdo_managed',true)||false!==strpos($p->post_content,'[gdo_')){wp_update_post(array('ID'=>$id,'post_content'=>'[gdo_doctor_application]'));}}if(!is_wp_error($id)){update_post_meta($id,'_gdo_managed','1');update_option('gdo_page_map',array('apply'=>$id),false);}GDO_Helpers::storage();update_option('gdo_version',GDO_VERSION,false);set_transient('gdo_notice','1',120);}
	public static function deactivate(){}
}

